/**
 * ELA — Duplicate Email Prevention Test
 *
 * Sends two identical requests to the local API,
 * using the same submission identifier.
 *
 * Expected:
 * - Both requests accepted
 * - Only ONE email generated by Resend
 *
 * Run this script once.
 */

const API_URL = "http://localhost:3000/api/enquiries";

const submissionId = "7c67511a-7df6-41ca-9cad-176b2bb137a6";
const testMarker = submissionId.slice(0, 8);

const enquiry = {
  name: `Duplicate Test ${testMarker}`,
  email: "test@example.com",
  phone: "",
  postcode: "WV1 1AA",
  contactMethod: "email",
  message: "This is a controlled test of ELA's duplicate email protection.",
  website: "",
  submissionId,
};

async function submitEnquiry(attempt) {
  console.log(`\nSubmitting request ${attempt}...`);

  const response = await fetch(API_URL, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Origin: "http://localhost:3000",
    },
    body: JSON.stringify(enquiry),
    signal: AbortSignal.timeout(15000),
  });

  const data = await response.json().catch(() => null);

  console.log(`HTTP status: ${response.status}`);
  console.log(`Email accepted: ${data?.emailAccepted ?? false}`);

  if (
    !response.ok ||
    data?.success !== true ||
    data?.testMode !== true ||
    data?.emailAccepted !== true ||
    data?.deliveryConfirmed !== false
  ) {
    console.error("The API did not confirm test email acceptance.");

    if (data?.code) {
      console.error(`Error code: ${data.code}`);
    }

    throw new Error(`Request ${attempt} failed.`);
  }
}

console.log("ELA Duplicate Email Prevention Test");
console.log(`Test marker: ${testMarker}`);
console.log(`Submission ID: ${submissionId}`);

console.log("\nTwo identical requests will be made for one intended email.");

try {
  await submitEnquiry(1);
  await submitEnquiry(2);

  console.log("\nBoth requests were accepted.");
  console.log("Now verify that Resend created only one email.");

  console.log(
    `Expected subject: [ELA TEST] New enquiry — Duplicate Test ${testMarker}`,
  );
} catch (error) {
  console.error("\nTest failed:", error.message);
  process.exitCode = 1;
}
